const results = ($json.data && $json.data.results) || [];
const attachList = results
  .filter((r) => typeof r.excerpt === 'string' && r.excerpt.length > 0)
  .map((r) => ({ contactId: r.contactId, excerpt: r.excerpt }));
const messageId = $('Sub-workflow Input').item.json.messageId;
return [{ json: { attachList: attachList, messageId: messageId } }];

const attachList = $json.attachList;
const messageId = $json.messageId;
return attachList.map((item) => ({ json: { contactId: item.contactId, excerpt: item.excerpt, messageId: messageId } }));

const items = $input.all();
const matchedContactIds = items.filter((i) => i.json.matched).map((i) => i.json.contactId);
const messageId = items[0].json.messageId;
return [{ json: { matchedContactIds: matchedContactIds, messageId: messageId } }];
